package br.com.onda;
import android.app.Activity;
import android.content.*;
import android.media.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.media3.session.*;
import androidx.media3.session.MediaController;
import com.google.common.util.concurrent.ListenableFuture;
import org.videolan.libvlc.LibVLC;
import org.videolan.libvlc.Media;
import org.videolan.libvlc.MediaPlayer;
import org.videolan.libvlc.util.VLCVideoLayout;
import java.util.*;
/** Native foreground-only streaming; leaving stops network/decoder and releases audio focus. */
@androidx.media3.common.util.UnstableApi
public class IptvPlayerActivity extends Activity {
 private LibVLC engine;private MediaPlayer video;private VLCVideoLayout surface;private TextView status;private LinearLayout controls;private Button play;private String url="";private boolean requested,started,initial=true,opened,software,receiverRegistered;private long frames;private AudioManager audio;private AudioFocusRequest focus;private ListenableFuture<MediaController> connection;private MediaController music;private final Handler handler=new Handler(Looper.getMainLooper());private final Runnable hide=()->{if(started&&video!=null&&video.isPlaying())controls.setVisibility(View.GONE);};
 private final BroadcastReceiver noisy=new BroadcastReceiver(){public void onReceive(Context c,Intent i){pause();}};
 @Override public void onCreate(Bundle saved){super.onCreate(saved);url=IptvPlaylist.stream(getIntent().getStringExtra("url"),"");FrameLayout root=new FrameLayout(this);root.setBackgroundColor(android.graphics.Color.BLACK);setContentView(root);surface=new VLCVideoLayout(this);root.addView(surface,new FrameLayout.LayoutParams(-1,-1));status=Ui.text(this,"Preparando canal…",16,android.graphics.Color.WHITE);status.setGravity(Gravity.CENTER);root.addView(status,new FrameLayout.LayoutParams(-1,-1));status.setClickable(false);controls=new LinearLayout(this);controls.setGravity(Gravity.CENTER_VERTICAL);controls.setPadding(Ui.dp(this,12),Ui.dp(this,12),Ui.dp(this,12),Ui.dp(this,12));controls.setBackgroundColor(0xcc10151f);Button back=Ui.button(this,"‹",v->finish());back.setContentDescription("Voltar dos canais IPTV");controls.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,48),-2));TextView title=Ui.text(this,getIntent().getStringExtra("title"),18,android.graphics.Color.WHITE);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);controls.addView(title,new LinearLayout.LayoutParams(0,-2,1));play=Ui.button(this,"▶",v->{if(video!=null&&video.isPlaying())pause();else open();});play.setContentDescription("Reproduzir canal IPTV");controls.addView(play,new LinearLayout.LayoutParams(Ui.dp(this,56),-2));root.addView(controls,new FrameLayout.LayoutParams(-1,-2,Gravity.TOP));root.setOnTouchListener((v,e)->{if(e.getActionMasked()==android.view.MotionEvent.ACTION_UP){showControls();return true;}return true;});surface.setOnTouchListener((v,e)->{if(e.getActionMasked()==android.view.MotionEvent.ACTION_UP)showControls();return true;});getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);immersive();if(url.isEmpty()){status.setText("Endereço de canal inválido. Use um fluxo HTTP ou HTTPS.");play.setEnabled(false);return;}
  try{engine=new LibVLC(this,new ArrayList<>(Arrays.asList("--no-video-title-show","--no-stats","--network-caching=1500")));video=new MediaPlayer(engine);video.attachViews(surface,null,true,false);video.setEventListener(e->{if(isDestroyed()||!started||!requested)return;switch(e.type){case MediaPlayer.Event.Playing:status.setText("");play.setText("❚❚");play.setContentDescription("Pausar canal IPTV");getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);showControls();break;case MediaPlayer.Event.Buffering:if(e.getBuffering()<100&&started)status.setText("Carregando transmissão…");else if(video.isPlaying())status.setText("");break;case MediaPlayer.Event.Vout:if(e.getVoutCount()>0)frames++;break;case MediaPlayer.Event.EncounteredError:if(!software&&started){software=true;open();}else fail();break;case MediaPlayer.Event.EndReached:pause();status.setText("A transmissão terminou. Toque em Reproduzir para reconectar.");break;default:break;}});}catch(RuntimeException|LinkageError e){status.setText("O player não pôde iniciar neste aparelho.");play.setEnabled(false);return;}
  audio=(AudioManager)getSystemService(AUDIO_SERVICE);focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MOVIE).build()).setOnAudioFocusChangeListener(change->{if(video==null)return;if(change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK)video.setVolume(25);else if(change==AudioManager.AUDIOFOCUS_GAIN)video.setVolume(100);else pause();},handler).build();androidx.core.content.ContextCompat.registerReceiver(this,noisy,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY),androidx.core.content.ContextCompat.RECEIVER_NOT_EXPORTED);receiverRegistered=true;connection=new MediaController.Builder(this,new SessionToken(this,new ComponentName(this,PlaybackService.class))).buildAsync();connection.addListener(()->{if(isDestroyed())return;try{music=connection.get();if(initial&&started){initial=false;open();}}catch(Exception e){status.setText("Não foi possível preparar o áudio.");}},handler::post);
 }
 private void immersive(){getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_LAYOUT_STABLE);}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)immersive();}
 private void showControls(){controls.setVisibility(View.VISIBLE);handler.removeCallbacks(hide);if(video!=null&&video.isPlaying())handler.postDelayed(hide,3000);}
 private void open(){if(!started||video==null||music==null)return;VideoBackgroundService.stopForMusic(this);music.pause();if(audio.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){status.setText("Áudio ocupado por outro aplicativo.");return;}video.stop();video.detachViews();video.attachViews(surface,null,true,false);Media media=new Media(engine,android.net.Uri.parse(url));try{media.setHWDecoderEnabled(!software,false);video.setMedia(media);}finally{media.release();}opened=true;requested=true;status.setText("Conectando ao canal…");video.play();showControls();}
 private void pause(){requested=false;handler.removeCallbacks(hide);if(video!=null)video.stop();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(audio!=null&&focus!=null)audio.abandonAudioFocusRequest(focus);if(play!=null){play.setText("▶");play.setContentDescription("Reproduzir canal IPTV");}if(controls!=null)controls.setVisibility(View.VISIBLE);}
 private void fail(){pause();status.setText("Canal indisponível ou incompatível. Confira sua lista, a conexão e o acesso ao servidor. Toque em Reproduzir para tentar novamente.");}
 @Override protected void onStart(){super.onStart();started=true;if(initial&&music!=null){initial=false;open();}}
 @Override protected void onPause(){pause();super.onPause();}
 @Override protected void onStop(){started=false;initial=false;if(video!=null)video.stop();if(opened)status.setText("Pausado • toque em Reproduzir para reconectar.");super.onStop();}
 @Override protected void onDestroy(){started=false;requested=false;handler.removeCallbacksAndMessages(null);if(receiverRegistered)unregisterReceiver(noisy);if(connection!=null)MediaController.releaseFuture(connection);if(video!=null){video.setEventListener(null);video.stop();video.detachViews();video.release();}if(engine!=null)engine.release();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(audio!=null&&focus!=null)audio.abandonAudioFocusRequest(focus);super.onDestroy();}
}
